package com.nequard.monitoring;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="metric_snapshots") public class MetricSnapshot{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)UUID deviceId;@Column(nullable=false)Instant recordedAt;Double latencyMs,packetLossPercent,cpuPercent,memoryPercent,bandwidthMbps;String status;public UUID getId(){return id;}public UUID getDeviceId(){return deviceId;}public void setDeviceId(UUID v){deviceId=v;}public Instant getRecordedAt(){return recordedAt;}public void setRecordedAt(Instant v){recordedAt=v;}public Double getLatencyMs(){return latencyMs;}public void setLatencyMs(Double v){latencyMs=v;}public Double getPacketLossPercent(){return packetLossPercent;}public void setPacketLossPercent(Double v){packetLossPercent=v;}public Double getCpuPercent(){return cpuPercent;}public void setCpuPercent(Double v){cpuPercent=v;}public Double getMemoryPercent(){return memoryPercent;}public void setMemoryPercent(Double v){memoryPercent=v;}public Double getBandwidthMbps(){return bandwidthMbps;}public void setBandwidthMbps(Double v){bandwidthMbps=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}}